-- Component configurator data. Parametric geometry is generated by the local Three.js client.
ALTER TABLE products MODIFY customization_preview_kind ENUM('generic','sofa','coffee_table','bed','dining_table','wardrobe') NOT NULL DEFAULT 'generic';

CREATE TABLE product_components (
  component_id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  product_id INT UNSIGNED NOT NULL,
  component_key VARCHAR(60) NOT NULL,
  display_name VARCHAR(100) NOT NULL,
  geometry_type VARCHAR(32) NOT NULL,
  layout_axis VARCHAR(16) NOT NULL DEFAULT 'none',
  is_active TINYINT(1) NOT NULL DEFAULT 1,
  default_shape VARCHAR(32) NOT NULL,
  allowed_shapes_json LONGTEXT NOT NULL,
  shape_prices_json LONGTEXT NOT NULL,
  default_material VARCHAR(100) NOT NULL DEFAULT 'Oak',
  default_color_hex CHAR(7) NOT NULL DEFAULT '#B88752',
  default_texture_key VARCHAR(24) NOT NULL DEFAULT 'oak',
  default_finish VARCHAR(100) NOT NULL DEFAULT 'Matte',
  default_width_cm DECIMAL(8,2) NOT NULL,
  min_width_cm DECIMAL(8,2) NOT NULL,
  max_width_cm DECIMAL(8,2) NOT NULL,
  default_depth_cm DECIMAL(8,2) NOT NULL,
  min_depth_cm DECIMAL(8,2) NOT NULL,
  max_depth_cm DECIMAL(8,2) NOT NULL,
  default_height_cm DECIMAL(8,2) NOT NULL,
  min_height_cm DECIMAL(8,2) NOT NULL,
  max_height_cm DECIMAL(8,2) NOT NULL,
  default_quantity SMALLINT UNSIGNED NOT NULL DEFAULT 1,
  min_quantity SMALLINT UNSIGNED NOT NULL DEFAULT 0,
  max_quantity SMALLINT UNSIGNED NOT NULL DEFAULT 20,
  default_x_cm DECIMAL(8,2) NOT NULL DEFAULT 0,
  min_x_cm DECIMAL(8,2) NOT NULL DEFAULT -200,
  max_x_cm DECIMAL(8,2) NOT NULL DEFAULT 200,
  default_y_cm DECIMAL(8,2) NOT NULL DEFAULT 0,
  min_y_cm DECIMAL(8,2) NOT NULL DEFAULT -200,
  max_y_cm DECIMAL(8,2) NOT NULL DEFAULT 250,
  default_z_cm DECIMAL(8,2) NOT NULL DEFAULT 0,
  min_z_cm DECIMAL(8,2) NOT NULL DEFAULT -200,
  max_z_cm DECIMAL(8,2) NOT NULL DEFAULT 200,
  unit_price DECIMAL(10,2) NOT NULL DEFAULT 0,
  width_rate DECIMAL(10,2) NOT NULL DEFAULT 0,
  depth_rate DECIMAL(10,2) NOT NULL DEFAULT 0,
  height_rate DECIMAL(10,2) NOT NULL DEFAULT 0,
  UNIQUE KEY uq_product_component(product_id,component_key),
  KEY idx_component_product(product_id,is_active),
  CONSTRAINT fk_component_product FOREIGN KEY(product_id) REFERENCES products(product_id) ON DELETE CASCADE,
  CHECK(max_width_cm>=min_width_cm AND default_width_cm BETWEEN min_width_cm AND max_width_cm),
  CHECK(max_depth_cm>=min_depth_cm AND default_depth_cm BETWEEN min_depth_cm AND max_depth_cm),
  CHECK(max_height_cm>=min_height_cm AND default_height_cm BETWEEN min_height_cm AND max_height_cm),
  CHECK(max_quantity>=min_quantity AND default_quantity BETWEEN min_quantity AND max_quantity)
) ENGINE=InnoDB;

CREATE TABLE product_component_options (
  component_option_id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  component_id INT UNSIGNED NOT NULL,
  option_type ENUM('material','color','finish') NOT NULL,
  option_name VARCHAR(100) NOT NULL,
  color_hex CHAR(7) NOT NULL DEFAULT '#A98568',
  texture_key VARCHAR(24) NOT NULL DEFAULT 'solid',
  additional_cost DECIMAL(10,2) NOT NULL DEFAULT 0,
  is_active TINYINT(1) NOT NULL DEFAULT 1,
  UNIQUE KEY uq_component_option(component_id,option_type,option_name),
  CONSTRAINT fk_component_option_component FOREIGN KEY(component_id) REFERENCES product_components(component_id) ON DELETE CASCADE
) ENGINE=InnoDB;

CREATE TABLE cart_item_component_snapshots (
  snapshot_id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  cart_item_id INT UNSIGNED NOT NULL,
  component_key VARCHAR(60) NOT NULL,
  component_label VARCHAR(100) NOT NULL,
  spec_json LONGTEXT NOT NULL,
  additional_cost DECIMAL(10,2) NOT NULL DEFAULT 0,
  CONSTRAINT fk_cart_component_item FOREIGN KEY(cart_item_id) REFERENCES cart_items(cart_item_id) ON DELETE CASCADE
) ENGINE=InnoDB;

CREATE TABLE order_item_component_snapshots (
  snapshot_id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  order_item_id INT UNSIGNED NOT NULL,
  component_key VARCHAR(60) NOT NULL,
  component_label VARCHAR(100) NOT NULL,
  spec_json LONGTEXT NOT NULL,
  additional_cost DECIMAL(10,2) NOT NULL DEFAULT 0,
  CONSTRAINT fk_order_component_item FOREIGN KEY(order_item_id) REFERENCES order_items(order_item_id) ON DELETE RESTRICT
) ENGINE=InnoDB;

INSERT INTO products(category_id,name,description,base_price,availability,is_customizable,default_width_cm,default_height_cm,default_depth_cm,customization_preview_kind)
SELECT category_id,'Modular Wardrobe Pilot','Parametric wardrobe with configurable doors, drawers, shelves, compartments, handles and feet.',1499,'In Stock',1,160,220,60,'wardrobe'
FROM categories WHERE category_name='Bedroom' AND NOT EXISTS(SELECT 1 FROM products WHERE name='Modular Wardrobe Pilot') LIMIT 1;

