-- Per-component surface options. Procedural local textures are generated by the viewer; no remote model or image is used.
INSERT IGNORE INTO product_component_options(component_id,option_type,option_name,color_hex,texture_key,additional_cost)
SELECT c.component_id,'material',m.option_name,m.color_hex,m.texture_key,m.cost FROM product_components c JOIN (
 SELECT 'Oak' option_name,'#B88752' color_hex,'oak' texture_key,35.00 cost UNION ALL
 SELECT 'Walnut','#583D2E','walnut',55 UNION ALL SELECT 'Performance weave','#A98568','fabric',40 UNION ALL SELECT 'Velvet','#737A8C','velvet',65 UNION ALL SELECT 'Leather','#624638','leather',95 UNION ALL SELECT 'Brushed steel','#999C9E','metal',45
) m ON 1=1;
